import math
from typing import List, Dict

def calculate_intersection_area(x: float, y: float, radius: float, polygon: List[tuple]) -> float:
    """
    Calculates the area of the intersection between a circle centered at (x, y) and a polygon given by vertices (x01, y01)...(xn, yn).
    """
    area = 0.0
    n = len(polygon)
    for i in range(n):
        p1 = polygon[i]
        p2 = polygon[(i + 1) % n]
        if p1[0] == y:
            if (x - p1[0])**2 <= (radius**2 - (p1[1] - y)**2):
                area += 2.0 if i % 2 == 0 else -2.0
        elif p1[1] == y:
            if (x - p1[1])**2 <= (radius**2 - (p1[0] - y)**2):
                area += 2.0 if i % 2 == 0 else -2.0
        else:
            break
    area += calculate_triangle_area(x, y, polygon[0], polygon[1])
    return area

def calculate_triangle_area(x1: float, y1: float, x2: float, y2: float) -> float:
    """
    Calculates the area of a triangle formed by the three points (x1, y1), (x2, y2) and the center of the circle.
    """
    if (x1 == x2) and (y1 == y2):
        return 0.0 / 2.0
    a = abs(x2 - x1)
    b = abs(y2 - y1)
    c = math.hypot(x2 - x1, y2 - y1)
    return (a+b+c) / 2

