import sys
from functools import reduce

def modular_power(x, n, mod):
    result = 1
    multiple = x % mod
    while n:
        if n & 1:
            result = (result * multiple) % mod
        multiple = (multiple * multiple) % mod
        n //= 2
    return result

def modular_inverse(x, mod):
    return modular_power(x, mod-2, mod)

T = int(sys.stdin.readline())
for _ in range(T):
    N = int(sys.stdin.readline())
    A = list(map(int, sys.stdin.readline().strip().split()))
    mod = 998244353

    # Let P_1 be the position of country i in P when A_i != 1
    # Let P_i be the position of country i in P when A_i == 1
    # The number of cyclic routes starting from country i is
    # f1 = (N - 1) * P_P1 * P_1 + 1 if A_i != 1
    # or f0 = P_1 + 1 if A_i == 1
    # (the loop is required for setting up cases when the list has duplicates)

    def f1(P):
        return reduce(lambda x, y: (x * y // 2) + 1, P, 0) if A[P] != 1 else reduce(lambda x, y: x + y, P, 1)

    def f0(P):
        return 1 + reduce(lambda x, y: x + y, P)

    # Number of permutations (cyclic routes start from a specific country i)
    # can be generally be calculated as f1(P_i) - f0(P_1)
    # Here we upper bound the permuation by size of set of countries

    perms = 1
    for i in range(1, N+1):
        if A[i-1] == 1:
            perm = f1(range(1, i+1) + range(N, i-1, -1))
        else:
            perm = f0(range(1, i+1) + range(N, i-1, -1))
        perms *= perm
        perms %= mod

    print(perms)
